"s,@DEFS@,-DPACKAGE=\\\"resid\\\" -DVERSION=\\\"0.13\\\" -DSTDC_HEADERS=1 -DHAVE_SYS_TYPES_H=1 -DHAVE_SYS_STAT_H=1 -DHAVE_STDLIB_H=1 -DHAVE_STRING_H=1 -DHAVE_MEMORY_H=1 -DHAVE_STRINGS_H=1 -DHAVE_INTTYPES_H=1 -DHAVE_STDINT_H=1 -DHAVE_UNISTD_H=1 -DSIZEO"
"F_INT=4 ,;t t\n"
"s,@LIBS@,,;t t\n"
"s,@INSTALL_PROGRAM@,${INSTALL},;t t\n"
"s,@INSTALL_SCRIPT@,${INSTALL},;t t\n"
"s,@INSTALL_DATA@,${INSTALL} -m 644,;t t\n"
"s,@PACKAGE@,resid,;t t\n"
"s,@VERSION@,0.13,;t t\n"
"s,@ACLOCAL@,aclocal,;t t\n"
"s,@AUTOCONF@,autoconf,;t t\n"
"s,@AUTOMAKE@,automake,;t t\n"
"s,@AUTOHEADER@,autoheader,;t t\n"
"s,@MAKEINFO@,makeinfo,;t t\n"
"s,@SET_MAKE@,,;t t\n"
"s,@RESID_INLINING@,1,;t t\n"
"s,@RESID_INLINE@,inline,;t t\n"
"s,@CXX@,gcc3,;t t\n"
"s,@CXXFLAGS@,-g -Wall -O2 -funroll-loops -fomit-frame-pointer -fno-exceptions,;t t\n"
"s,@LDFLAGS@,,;t t\n"
"s,@CPPFLAGS@,,;t t\n"
"s,@ac_ct_CXX@,,;t t\n"
"s,@EXEEXT@,,;t t\n"
"s,@OBJEXT@,o,;t t\n"
"s,@PERL@,/usr/bin/perl,;t t\n"
"s,@build@,powerpc-apple-darwin6.1,;t t\n"
"s,@build_cpu@,powerpc,;t t\n"
"s,@build_vendor@,apple,;t t\n"
"s,@build_os@,darwin6.1,;t t\n"
"s,@host@,powerpc-apple-darwin6.1,;t t\n"
"s,@host_cpu@,powerpc,;t t\n"
"s,@host_vendor@,apple,;t t\n"
"s,@host_os@,darwin6.1,;t t\n"
"s,@RANLIB@,ranlib,;t t\n"
"s,@ac_ct_RANLIB@,ranlib,;t t\n"
"s,@CC@,gcc,;t t\n"
"s,@CFLAGS@,-g -O2,;t t\n"
"s,@ac_ct_CC@,gcc,;t t\n"
"s,@LN_S@,ln -s,;t t\n"
"s,@LIBTOOL@,$(SHELL) $(top_builddir)/libtool,;t t\n"
"s,@LIBTOOL_DEPS@,./ltconfig ./ltmain.sh,;t t\n"
"s,@LTVERSION@,2:1:0,;t t\n"
"s,@CXXCPP@,gcc3 -E,;t t\n"
"s,@RESID_HAVE_BOOL@,1,;t t\n"
"CEOF\n"
"\n"
"  # Split the substitutions into bite-sized pieces for seds with\n"
"  # small command number limits, like on Digital OSF/1 and HP-UX.\n"
"  ac_max_sed_lines=48\n"
"  ac_sed_frag=1 # Number of current file.\n"
"  ac_beg=1 # First line for current file.\n"
"  ac_end=$ac_max_sed_lines # Line after last line for current file.\n"
"  ac_more_lines=:\n"
"  ac_sed_cmds=\n"
"  while $ac_more_lines; do\n"
"    if test $ac_beg -gt 1; then\n"
"      sed \"1,${ac_beg}d; ${ac_end}q\" $tmp/subs.sed >$tmp/subs.frag\n"
"    else\n"
"      sed \"${ac_end}q\" $tmp/subs.sed >$tmp/subs.frag\n"
"    fi\n"
"    if test ! -s $tmp/subs.frag; then\n"
"      ac_more_lines=false\n"
"    else\n"
"      # The purpose of the label and of the branching condition is to\n"
"      # speed up the sed processing (if there are no `@' at all, there\n"
"      # is no need to browse any of the substitutions).\n"
"      # These are the two extra sed commands mentioned above.\n"
"      (echo ':t\n"
"  /@[a-zA-Z_][a-zA-Z_0-9]*@/!b' && cat $tmp/subs.frag) >$tmp/subs-$ac_sed_frag.sed\n"
"      if test -z \"$ac_sed_cmds\"; then\n"
"  \tac_sed_cmds=\"sed -f $tmp/subs-$ac_sed_frag.sed\"\n"
"      else\n"
"  \tac_sed_cmds=\"$ac_sed_cmds | sed -f $tmp/subs-$ac_sed_frag.sed\"\n"
"      fi\n"
"      ac_sed_frag=`expr $ac_sed_frag + 1`\n"
"      ac_beg=$ac_end\n"
"      ac_end=`expr $ac_end + $ac_max_sed_lines`\n"
"    fi\n"
"  done\n"
"  if test -z \"$ac_sed_cmds\"; then\n"
"    ac_sed_cmds=cat\n"
"  fi\n"
"fi # test -n \"$CONFIG_FILES\"\n"
"\n"
"for ac_file in : $CONFIG_FILES; do test \"x$ac_file\" = x: && continue\n"
"  # Support \"outfile[:infile[:infile...]]\", defaulting infile=\"outfile.in\".\n"
"  case $ac_file in\n"
"  - | *:- | *:-:* ) # input from stdin\n"
"        cat >$tmp/stdin\n"
"        ac_file_in=`echo \"$ac_file\" | sed 's,[^:]*:,,'`\n"
"        ac_file=`echo \"$ac_file\" | sed 's,:.*,,'` ;;\n"
"  *:* ) ac_file_in=`echo \"$ac_file\" | sed 's,[^:]*:,,'`\n"
"        ac_file=`echo \"$ac_file\" | sed 's,:.*,,'` ;;\n"
"  * )   ac_file_in=$ac_file.in ;;\n"
"  esac\n"
"\n"
"  # Compute @srcdir@, @top_srcdir@, and @INSTALL@ for subdirectories.\n"
"  ac_dir=`$as_expr X\"$ac_file\" : 'X\\(.*[^/]\\)//*[^/][^/]*/*$' \\| \\\n"
"         X\"$ac_file\" : 'X\\(//\\)[^/]' \\| \\\n"
"         X\"$ac_file\" : 'X\\(//\\)$' \\| \\\n"
"         X\"$ac_file\" : 'X\\(/\\)' \\| \\\n"
"         .     : '\\(.\\)' 2>/dev/null ||\n"
"echo X\"$ac_file\" |\n"
"    sed '/^X\\(.*[^/]\\)\\/\\/*[^/][^/]*\\/*$/{ s//\\1/; q; }\n"
"  \t  /^X\\(\\/\\/\\)[^/].*/{ s//\\1/; q; }\n"
"  \t  /^X\\(\\/\\/\\)$/{ s//\\1/; q; }\n"
"  \t  /^X\\(\\/\\).*/{ s//\\1/; q; }\n"
"  \t  s/.*/./; q'`\n"
"  if test \"$ac_dir\" != \"$ac_file\" && test \"$ac_dir\" != .; then\n"
"    { case \"$ac_dir\" in\n"
"  [\\\\/]* | ?:[\\\\/]* ) as_incr_dir=;;\n"
"  *)                      as_incr_dir=.;;\n"
"esac\n"
"as_dummy=\"$ac_dir\"\n"
"for as_mkdir_dir in `IFS='/\\\\'; set X $as_dummy; shift; echo \"$@\"`; do\n"
"  case $as_mkdir_dir in\n"
"    # Skip DOS drivespec\n"
"    ?:) as_incr_dir=$as_mkdir_dir ;;\n"
"    *)\n"
"      as_incr_dir=$as_incr_dir/$as_mkdir_dir\n"
"      test -d \"$as_incr_dir\" || mkdir \"$as_incr_dir\"\n"
"    ;;\n"
"  esac\n"
"done; }\n"
"\n"
"    ac_dir_suffix=\"/`echo $ac_dir|sed 's,^\\./,,'`\"\n"
"    # A \"../\" for each directory in $ac_dir_suffix.\n"
"    ac_dots=`echo \"$ac_dir_suffix\" | sed 's,/[^/]*,../,g'`\n"
"  else\n"
"    ac_dir_suffix= ac_dots=\n"
"  fi\n"
"\n"
"  case $srcdir in\n"
"  .)  ac_srcdir=.\n"
"      if test -z \"$ac_dots\"; then\n"
"         ac_top_srcdir=.\n"
"      else\n"
"         ac_top_srcdir=`echo $ac_dots | sed 's,/$,,'`\n"
"      fi ;;\n"
"  [\\\\/]* | ?:[\\\\/]* )\n"
"      ac_srcdir=$srcdir$ac_dir_suffix;\n"
"      ac_top_srcdir=$srcdir ;;\n"
"  *) # Relative path.\n"
"    ac_srcdir=$ac_dots$srcdir$ac_dir_suffix\n"
"    ac_top_srcdir=$ac_dots$srcdir ;;\n"
"  esac\n"
"\n"
"  case $INSTALL in\n"
"  [\\\\/$]* | ?:[\\\\/]* ) ac_INSTALL=$INSTALL ;;\n"
"  *) ac_INSTALL=$ac_dots$INSTALL ;;\n"
"  esac\n"
"\n"
"  if test x\"$ac_file\" != x-; then\n"
"    { echo \"$as_me:4129: creating $ac_file\" >&5\n"
"echo \"$as_me: creating $ac_file\" >&6;}\n"
"    rm -f \"$ac_file\"\n"
"  fi\n"
"  # Let's still pretend it is `configure' which instantiates (i.e., don't\n"
"  # use $as_me), people would be surprised to read:\n"
"  #    /* config.h.  Generated automatically by config.status.  */\n"
"  configure_input=\"Generated automatically from `echo $ac_file_in |\n"
"                                                 sed 's,.*/,,'` by configure.\"\n"
"\n"
"  # First look for the input files in the build tree, otherwise in the\n"
"  # src tree.\n"
"  ac_file_inputs=`IFS=:\n"
"    for f in $ac_file_in; do\n"
"      case $f in\n"
"      -) echo $tmp/stdin ;;\n"
"      [\\\\/$]*)\n"
"         # Absolute (can't be DOS-style, as IFS=:)\n"
"         test -f \"$f\" || { { echo \"$as_me:4147: error: cannot find input file: $f\" >&5\n"
"echo \"$as_me: error: cannot find input file: $f\" >&2;}\n"
"   { (exit 1); exit 1; }; }\n"
"         echo $f;;\n"
"      *) # Relative\n"
"         if test -f \"$f\"; then\n"
"           # Build tree\n"
"           echo $f\n"
"         elif test -f \"$srcdir/$f\"; then\n"
"           # Source tree\n"
"           echo $srcdir/$f\n"
"         else\n"
"           # /dev/null tree\n"
"           { { echo \"$as_me:4160: error: cannot find input file: $f\" >&5\n"
"echo \"$as_me: error: cannot find input file: $f\" >&2;}\n"
"   { (exit 1); exit 1; }; }\n"
"         fi;;\n"
"      esac\n"
"    done` || { (exit 1); exit 1; }\n"
"  sed \"/^[ \t]*VPATH[ \t]*=/{\n"
"s/:*\\$(srcdir):*/:/;\n"
"s/:*\\${srcdir}:*/:/;\n"
"s/:*@srcdir@:*/:/;\n"
"s/^\\([^=]*=[ \t]*\\):*/\\1/;\n"
"s/:*$//;\n"
"s/^[^=]*=[ \t]*$//;\n"
"}\n"
"\n"
":t\n"
"/@[a-zA-Z_][a-zA-Z_0-9]*@/!b\n"
"s,@configure_input@,$configure_input,;t t\n"
"s,@srcdir@,$ac_srcdir,;t t\n"
"s,@top_srcdir@,$ac_top_srcdir,;t t\n"
"s,@INSTALL@,$ac_INSTALL,;t t\n"
"\" $ac_file_inputs | (eval \"$ac_sed_cmds\") >$tmp/out\n"
"  rm -f $tmp/stdin\n"
"  if test x\"$ac_file\" != x-; then\n"
"    mv $tmp/out $ac_file\n"
"  else\n"
"    cat $tmp/out\n"
"    rm -f $tmp/out\n"
"  fi\n"
"\n"
"done\n"
"\n"
"{ (exit 0); exit 0; }\n";

